        /** @return array{status: array, payment: array, fulfilment: array} label and variant of every status, payment and fulfilment state */
        function nq_store_admin_labels(): array
        {
            static $all = null;
            $all ??= json_decode(<<<'JSON'
{"status":{"pending":["Pending","قيد الانتظار","warning"],"paid":["Paid","مدفوع","info"],"processing":["Processing","قيد التجهيز","info"],"partially-fulfilled":["Partly shipped","شُحن جزئيًا","info"],"fulfilled":["Fulfilled","تم التجهيز","info"],"shipped":["Shipped","تم الشحن","info"],"out-for-delivery":["Out for delivery","في الطريق إليك","info"],"delivered":["Delivered","تم التسليم","success"],"cancelled":["Cancelled","ملغي","neutral"],"refunded":["Refunded","تم الاسترداد","neutral"],"partially-refunded":["Partly refunded","استرداد جزئي","warning"],"returned":["Returned","مرتجع","neutral"]},"payment":{"pending":["Unpaid","غير مدفوع","warning"],"authorized":["Authorised","محجوز","info"],"paid":["Paid","مدفوع","success"],"partially-refunded":["Partly refunded","استرداد جزئي","warning"],"refunded":["Refunded","تم الاسترداد","neutral"],"failed":["Failed","فشل الدفع","danger"],"cod":["Cash on delivery","الدفع عند الاستلام","info"]},"fulfilment":{"unfulfilled":["Unfulfilled","لم يُجهَّز","warning"],"partial":["Partly fulfilled","مجهّز جزئيًا","info"],"fulfilled":["Fulfilled","مجهّز","success"],"none":["Nothing to ship","لا شيء للشحن","neutral"]}}
JSON, true);
            $i = \Nasaq\Nasaq::rtl() ? 1 : 0;
            $out = [];
            foreach ($all as $group => $items) {
                foreach ($items as $key => $row) {
                    $out[$group][$key] = ['label' => $row[$i], 'variant' => $row[2]];
                }
            }

            return $out;
        }

        /** Minor units as text for server-rendered money: 1800 -> "$18.00". */
        function nq_store_admin_money(int|float $minor, ?string $currency = null, bool $negative = false): string
        {
            $currency ??= \Nasaq\Nasaq::currency(app()->getLocale());
            $factor = $currency === 'JPY' ? 1 : (in_array($currency, ['KWD', 'BHD', 'OMR', 'JOD', 'TND'], true) ? 1000 : 100);

            return \Nasaq\Nasaq::money(($negative ? -abs($minor) : $minor) / $factor, $currency);
        }
    }
